    81→/**
    82→ * Exponentiation of a field element.
    83→ *
    84→ * Uses square and multiply for log(n) performance.
    85→ *
    86→ * @param[out]  out The result, `a**n`
    87→ * @param[in]   a   The field element to be exponentiated
    88→ * @param[in]   n   The exponent
    89→ *
    90→ * @remark A 64-bit exponent is sufficient for our needs here.
    91→ * @remark This function does support in-place computation.
    92→ */
    93→void fr_pow(fr_t *out, const fr_t *a, uint64_t n) {
    94→    fr_t tmp = *a;
    95→    *out = FR_ONE;
    96→
    97→    while (true) {
    98→        if (n & 1) {
    99→            blst_fr_mul(out, out, &tmp);
   100→        }
