   107→// DeserializeBlob implements [blob_to_polynomial].
   108→//
   109→// [blob_to_polynomial]: https://github.com/ethereum/consensus-specs/blob/017a8495f7671f5fff2075a9bfc9238c1a0982f8/specs/deneb/polynomial-commitments.md#blob_to_polynomial
   110→func DeserializeBlob(blob *Blob) (kzg.Polynomial, error) {
   111→	poly := make(kzg.Polynomial, ScalarsPerBlob)
   112→	for i := 0; i < ScalarsPerBlob; i++ {
   113→		chunk := blob[i*SerializedScalarSize : (i+1)*SerializedScalarSize]
   114→		if err := poly[i].SetBytesCanonical(chunk); err != nil {
   115→			return nil, ErrNonCanonicalScalar
   116→		}
   117→	}
   118→	return poly, nil
   119→}
   120→
   121→// DeserializeScalar implements [bytes_to_bls_field].
   122→//
   123→// Note: Returns an error if the scalar is not in the range [0, p-1] (inclusive) where `p` is the prime associated with the scalar field.
   124→//
   125→// [bytes_to_bls_field]: https://github.com/ethereum/consensus-specs/blob/017a8495f7671f5fff2075a9bfc9238c1a0982f8/specs/deneb/polynomial-commitments.md#bytes_to_bls_field
   126→func DeserializeScalar(serScalar Scalar) (fr.Element, error) {
   127→	scalar, err := utils.ReduceCanonicalBigEndian(serScalar[:])
   128→	if err != nil {
   129→		return fr.Element{}, ErrNonCanonicalScalar
   130→	}
   131→	return scalar, nil
   132→}
   133→
   134→// SerializeScalar converts a [fr.Element] to [Scalar].
   135→func SerializeScalar(element fr.Element) Scalar {
   136→	return element.Bytes()
   137→}
   138→
   139→// SerializePoly converts a [kzg.Polynomial] to [Blob].
   140→//
   141→// Note: This method is never used in the API because we always expect a byte array and will never receive deserialized
   142→// field elements. We include it so that upstream fuzzers do not need to reimplement it.
   143→func SerializePoly(poly kzg.Polynomial) *Blob {
   144→	var blob Blob
   145→	for i := 0; i < ScalarsPerBlob; i++ {
   146→		chunk := blob[i*SerializedScalarSize : (i+1)*SerializedScalarSize]
   147→		serScalar := SerializeScalar(poly[i])
   148→		copy(chunk, serScalar[:])
   149→	}
   150→	return &blob
   151→}
